window.MINERAL_INDUSTRIAL_USE_EXTENSIONS = {"ima-halite":{"id":"ima-halite","name_en":"Halite","formula":"NaCl","verified_industrial_uses":{"status":"verified","value":["符合相应用途要求的岩盐产品可用于冬季步道除冰。","达到食品用途要求的盐可作调味剂。","达到化工原料要求的盐可用于制造氯气和烧碱；PVC 和造纸化学品属于这些化学原料的下游产品。"],"source_url":"https://www.usgs.gov/centers/national-minerals-information-center/salt-statistics-and-information","source_title":"Salt Statistics and Information | U.S. Geological Survey","source_section":"Introductory commodity description before Subscribe","retrieved_at":"2026-10-24","source_text_sha256":"0d8a795a9ed6e115b7c55c3582759ec7390ae6596fbd3476367dee3de08da4cb","commodity_scope_zh":"本条核对的是盐（氯化钠）商品用途。USGS 概览明确提及岩盐除冰，但盐商品用途不等于任何石盐晶体都可直接使用。Halite 的 NaCl 化学式仅按现有公开 IMA 目录作名称关联；本次未核定某份标本的纯度、污染物、食品级或化工级资格。食品用途条件是谨慎限定，不声称该概览提供了具体品级标准。","review_scope":"Chinese paraphrase checked against the cited USGS commodity source; not a measurement of the uploaded specimen."}},"ima-talc":{"id":"ima-talc","name_en":"Talc","formula":"Mg₃Si₄O₁₀(OH)₂","verified_industrial_uses":{"status":"verified","value":["达到相应用途规格的滑石产品用于陶瓷和涂料行业。","滑石产品也用于造纸和塑料行业。"],"source_url":"https://www.usgs.gov/centers/national-minerals-information-center/talc-and-pyrophyllite-statistics-and-information","source_title":"Talc and Pyrophyllite Statistics and Information | U.S. Geological Survey","source_section":"Introductory commodity description before Subscribe","retrieved_at":"2026-10-24","source_text_sha256":"1a2b51b627fcb0d0efe4570aeaec3958ad30809e321f5a9f5929f2db132299cd","commodity_scope_zh":"USGS 将滑石描述为含水镁硅酸盐，并在同页分别介绍滑石、富滑石块状岩石及叶蜡石。本条只采用明确属于 talc 段落的市场用途，不把叶蜡石耐火材料用途直接套给滑石，也不把任意滑石矿石或标本认作已达工业、化妆品或其他专用品级。","review_scope":"Chinese paraphrase checked against the cited USGS commodity source; not a measurement of the uploaded specimen."}}};
